import os
from azure.ai.formrecognizer import DocumentAnalysisClient
from azure.core.credentials import AzureKeyCredential

def extract_document_layout(file_path: str) -> dict:
    endpoint = os.environ.get("AZURE_FORM_RECOGNIZER_ENDPOINT")
    api_key = os.environ.get("AZURE_FORM_RECOGNIZER_KEY")
    if not endpoint or not api_key:
        raise ValueError("AZURE_FORM_RECOGNIZER_ENDPOINT and AZURE_FORM_RECOGNIZER_KEY must be set.")

    client = DocumentAnalysisClient(
        endpoint=endpoint,
        credential=AzureKeyCredential(api_key)
    )

    with open(file_path, "rb") as document:
        poller = client.begin_analyze_document(
            model_id="prebuilt-layout",
            document=document
        )
        result = poller.result()

    extracted_data = {
        "lines": [],
        "blocks": [],
        "tables": []
    }

    for page in result.pages:
        for paragraph in page.paragraphs:
            extracted_data["lines"].append({
                "page_number": page.page_number,
                "content": paragraph.content,
                "role": paragraph.role if hasattr(paragraph, "role") else None
            })

        if page.selection_marks:
            for mark in page.selection_marks:
                extracted_data["blocks"].append({
                    "type": "selection_mark",
                    "page_number": page.page_number,
                    "state": mark.state.value,
                    "confidence": mark.confidence
                })

    for table in result.tables:
        cells = []
        for cell in table.cells:
            cells.append({
                "row_index": cell.row_index,
                "column_index": cell.column_index,
                "content": cell.content,
                "is_header": cell.is_header
            })

        extracted_data["tables"].append({
            "page_number": table.bounding_regions[0].page_number if table.bounding_regions else None,
            "row_count": table.row_count,
            "column_count": table.column_count,
            "cells": cells
        })

    return extracted_data
